import React from "react"
import BlurredList from "./blurredlist"
import BlurHome from "./blurHome"
const LazyHome = React.lazy( () => import("../home") )
const LazyFoodCarts = React.lazy( () => import("../foodcards"))
const LazyRoomCarts = React.lazy( () => import('../roomcarts'))

const MainHome = () => {
    return(
        <>
            <React.Suspense fallback={< BlurHome />} >
                <LazyHome />
            </React.Suspense>
            <React.Suspense fallback={<BlurredList />} >
                <LazyRoomCarts />
                <button> </button>
                <LazyFoodCarts />
            </React.Suspense>
        </>
    )
}

export default MainHome
